export function launchKnowledge(record,catalog,hardware){
 if(record.category!=='launch')return null;
 const f=launchFleet[hardware?.input?.launcher];if(!f)return null;
 const key=record.id.slice('launch:'.length);let article;
 if(key==='vehicle')article=vehicleArticle(f);
 else if(key==='core'||key==='upper')article=stageArticle(f,key==='upper');
 else if(key==='core-engines'||key==='upper-engines')article=engineArticle(f,key==='upper-engines');
 else if(key==='fairing'||key==='fairing-shells')article=fairingArticle(f,key==='fairing-shells');
 else if(/^booster-\d+$/.test(key))article=boosterArticle(f);
 else if(['grid-fins','landing-legs','body-flaps'].includes(key))article=recoveryArticle(f,key);
 else if(key.startsWith('cargo-'))article=cargoArticle(f,key);
 else if(key.startsWith('umbilical-')||key.startsWith('connection-'))article=separationArticle(record);
 return article||null;
}
